// storyboard callbacks (story `code:`)
static void AnimTask_SW_Knockback_Step(u8 taskId)
{
    struct Task *task = &gTasks[taskId];
    struct Sprite *mon = &gSprites[task->data[0]];
    s16 t = task->data[5]++;
    s16 out = task->data[2], hold = task->data[3], back = task->data[4];

    if (t < out)
        mon->x2 = task->data[1] * (t + 1) / out;
    else if (t < out + hold)
        mon->x2 = task->data[1];
    else if (t < out + hold + back)
        mon->x2 = task->data[1] * (out + hold + back - t - 1) / back;
    else
    {
        mon->x2 = 0;
        DestroyAnimVisualTask(taskId);
    }
}

// Shove a battler away from the attacker and bring it home.
// args: battler, distance (px), out frames, hold frames, back frames
void AnimTask_SW_Knockback(u8 taskId)
{
    struct Task *task = &gTasks[taskId];
    u8 spriteId = GetAnimBattlerSpriteId(gBattleAnimArgs[0]);
    s16 dist = gBattleAnimArgs[1];

    u8 battler = gBattleAnimArgs[0] == ANIM_TARGET ? gBattleAnimTarget : gBattleAnimAttacker;

    if (GetBattlerSide(battler) == B_SIDE_PLAYER)
        dist = -dist;
    task->data[0] = spriteId;
    task->data[1] = dist;
    task->data[2] = gBattleAnimArgs[2];
    task->data[3] = gBattleAnimArgs[3];
    task->data[4] = gBattleAnimArgs[4];
    task->data[5] = 0;
    task->func = AnimTask_SW_Knockback_Step;
}
